import { DEFAULT_RULE, decide } from "./decision.ts";
import { explain } from "./explain.ts";
import { EXPECTED_SHARE, splitCheck } from "./srm.ts";
import type { Standings } from "./standings.ts";

const pct = (x: number) => `${Math.round(x * 100)}%`;
const signed = (x: number) => `${x >= 0 ? "+" : "-"}${Math.abs(Math.round(x * 100))}%`;
const rate = (c: number, n: number) => (n > 0 ? c / n : 0);

const SIMULATED_NOTE =
  "These results include simulated visitors. They are named `sim_<n>`, were generated by `scripts/simulate-traffic.ts`, and like a roast " +
  "at rates assumed in that script, not measured. Flagsmith cannot tell them from real visitors. They show that the pipeline works, " +
  "from exposure to event to Flagsmith's analysis, and say nothing about which prompt people prefer. See " +
  "`prereg/experiment-1-amendment-1.md`.";

/** docs/RESULTS.md: the latest results snapshot, written from the numbers only. Generated by `npm run finalize`; not edited by hand. */
export function renderResults(s: Standings): string {
  const total = s.variants.reduce((a, v) => a + v.exposures, 0);
  const split = splitCheck(s.variants, s.variants.map((v) => EXPECTED_SHARE[v.key] ?? 100 / s.variants.length));
  const d = decide(s, DEFAULT_RULE);
  const rows = s.variants.map((v) => {
    const lift = v.winProbability === null ? "baseline" : v.lift != null && v.ciLow != null && v.ciHigh != null ? `${signed(v.lift)} (${signed(v.ciLow)} to ${signed(v.ciHigh)})` : "not estimated yet";
    const win = v.winProbability === null ? "baseline" : pct(v.winProbability);
    return `| ${v.key} | ${v.exposures} | ${v.conversions} | ${pct(rate(v.conversions, v.exposures))} | ${win} | ${lift} |`;
  });
  const lines = [
    "# Results",
    "",
    `Generated by \`npm run finalize\` from Flagsmith's results for experiment 1048, as of ${s.updatedAt}. This file is rewritten each time, so it is not edited by hand.`,
    "",
    ...(s.simulated ? [`> **${SIMULATED_NOTE}**`, ""] : []),
    "## The numbers",
    "",
    `${total} visitors in total, on the primary metric "Roast liked" (the event \`thumbs_up\`).`,
    "",
    "| Arm | Visitors | Liked | Like rate | Win probability | Lift over control (95% interval) |",
    "|---|---|---|---|---|---|",
    ...rows,
    "",
    "Win probability is the figure Flagsmith's results call `chance_to_win`. It exists for each treatment and not for control, which is the baseline.",
    "",
    "## Is the split right?",
    "",
    "reason" in split
      ? split.reason
      : `Expected about ${split.expected.map((e) => Math.round(e)).join(" / ")} visitors across ${split.keys.join(", ")}, saw ${split.observed.join(" / ")} (chi-square p = ${split.p.toFixed(3)}). ${
          split.status === "ok" ? "The arms were filled in the proportions asked for." : "The arms are not balanced as designed, so these results should not be trusted until the cause is found."
        }`,
    ...(s.srmPValue != null ? ["", `Flagsmith's own sample-ratio check reports p = ${s.srmPValue.toFixed(3)}.`] : []),
    "",
    "## What it means",
    "",
    ...explain(s).map((l) => `- ${l}`),
    "",
    "## The decision under the pre-registered rule",
    "",
    d.action === "ship"
      ? `${d.reasons.join(" ")} A person still has to approve the rollout with \`npm run ship\`.`
      : `Nothing ships. ${d.reasons.join(" ")}`,
    "",
    `The rule, from \`prereg/experiment-1.md\`: a treatment ships only with at least a ${pct(DEFAULT_RULE.minWinProbability)} chance of beating control and ${DEFAULT_RULE.minExposuresPerArm} visitors in every arm. Simulated data never ships.`,
    "",
  ];
  return lines.join("\n");
}

/** The paragraph for the submission form's "what did the results show" box, written from the same numbers. */
export function formText(s: Standings): string {
  const total = s.variants.reduce((a, v) => a + v.exposures, 0);
  const arms = s.variants.map((v) => `${v.key} ${v.exposures}`).join(", ");
  const per = s.variants
    .map((v) => {
      const base = `${v.key}: ${v.conversions} of ${v.exposures} liked (${pct(rate(v.conversions, v.exposures))})`;
      if (v.winProbability === null) return `${base}, the baseline`;
      const ci = v.lift != null && v.ciLow != null && v.ciHigh != null ? `, lift ${signed(v.lift)} over control with a 95% interval from ${signed(v.ciLow)} to ${signed(v.ciHigh)}` : "";
      return `${base}, win probability ${pct(v.winProbability)}${ci}`;
    })
    .join("; ");
  const d = decide(s, DEFAULT_RULE);
  return [
    s.simulated
      ? `The traffic includes simulated visitors: ${total} visitors in all (${arms}), named sim_<n> and generated by scripts/simulate-traffic.ts with like rates assumed in that script (control 32%, savage 38%, actionable 50%). This demonstrates the pipeline end to end and says nothing about which prompt people prefer.`
      : `${total} visitors took part (${arms}).`,
    `Flagsmith's results on "Roast liked": ${per}.`,
    d.action === "ship"
      ? `Under the pre-registered rule (a 90% chance of beating control and 30 visitors in every arm), ${d.winner} qualifies to ship.`
      : `Under the pre-registered rule (a 90% chance of beating control and 30 visitors in every arm), nothing ships: ${d.reasons.join(" ")}`,
  ].join(" ");
}
